using System.Windows;using System.Windows.Controls;using System.Windows.Threading;namespace FFPerformanceEngine.App.Pages;public partial class PerformancePage:UserControl{private readonly DispatcherTimer _timer=new(){Interval=TimeSpan.FromSeconds(1)};public PerformancePage(){InitializeComponent();Loaded+=(_,_)=>{Refresh();_timer.Start();};Unloaded+=(_,_)=>_timer.Stop();_timer.Tick+=(_,_)=>Refresh();}private void Refresh(){var s=App.Services.Telemetry.CaptureSystemSample();CpuText.Text=s.CpuPercent is double cpu?$"{cpu:0}%":"—";RamText.Text=s.MemoryUsedGb is double used&&s.MemoryTotalGb is double total?$"{used:0.0}/{total:0.0} GB":"—";ProviderText.Text=App.Services.PresentMon.FindExecutable() is null?"Não instalado":"PresentMon pronto";}private async void Measure_Click(object s,RoutedEventArgs e){CaptureText.Text="Medindo...";var sample=await App.Services.PresentMon.CaptureAsync(TimeSpan.FromSeconds(10));CaptureText.Text=sample is null?"Captura indisponível. Verifique PresentMon e uma instância HD-Player ativa.":$"FPS {sample.Fps:0.0} · 1% low {sample.OnePercentLow:0.0} · 0.1% low {sample.PointOnePercentLow:0.0} · frame {sample.FrameTimeMs:0.00} ms · latência {(sample.LatencyMs?.ToString("0.0")??"—")} ms · qualidade {sample.DataQuality}.";}}